<?php

declare(strict_types=1);

namespace App_skeleton\Pdf;

/**
 * The fonts the `pdf` service embeds: DejaVu Sans, regular and bold, cut
 * into one single-byte font per Windows code page (fonts/, generated by
 * bin/make-pdf-fonts.php with FPDF's own makefont). Internal to
 * App_skeleton\Pdf.
 *
 * FPDF's fonts hold 256 characters each, so text outside one code page
 * is drawn by switching font: Western (cp1252), Central European
 * (cp1250), Cyrillic (cp1251), Greek (cp1253), Turkish (cp1254) and
 * Baltic (cp1257). This class answers the two questions that needs:
 * which byte a character is in a given code page, and how wide each byte
 * is. Both come from the generated definition files, so what can be
 * drawn is exactly what the embedded fonts contain.
 */
final class Fonts
{
    /** With a trailing slash, as FPDF's font path wants it. */
    public const DIR = __DIR__ . '/fonts/';

    /** In order of preference: a character goes to the first page that has it. */
    public const CODE_PAGES = ['cp1252', 'cp1250', 'cp1251', 'cp1253', 'cp1254', 'cp1257'];

    public const REGULAR = '';
    public const BOLD    = 'B';

    /** @var array<string, array<string, mixed>> definition file => its variables */
    private static array $definitions = [];

    /** @var array<string, array<int, int>> code page => Unicode code point => byte */
    private static array $bytes = [];

    /** @var array<string, array<int, int>> code page => byte => Unicode code point */
    private static array $codePoints = [];

    /** "DejaVuSans-Bold-cp1251.php": the definition file FPDF's AddFont() is given. */
    public static function file(string $codePage, string $style): string
    {
        return ($style === self::BOLD ? 'DejaVuSans-Bold-' : 'DejaVuSans-') . $codePage . '.php';
    }

    /** The family name the font is registered under in FPDF ("dejavucp1251"). */
    public static function family(string $codePage): string
    {
        return 'dejavu' . $codePage;
    }

    /** The byte for a character in a code page, or null when the page does not have it. */
    public static function byte(string $codePage, int $codePoint): ?int
    {
        if (!isset(self::$bytes[$codePage])) {
            self::map($codePage);
        }

        return self::$bytes[$codePage][$codePoint] ?? null;
    }

    /** The character a byte stands for in a code page (U+FFFD for a byte the page leaves unused). */
    public static function codePoint(string $codePage, int $byte): int
    {
        if (!isset(self::$codePoints[$codePage])) {
            self::map($codePage);
        }

        return self::$codePoints[$codePage][$byte] ?? 0xFFFD;
    }

    /**
     * Character widths of one font, in thousandths of the font size.
     *
     * @return array<string, int> one-byte string => width
     */
    public static function widths(string $codePage, string $style): array
    {
        return self::definition(self::file($codePage, $style))['cw'];
    }

    /** The width of a string of one font, in thousandths of the font size. */
    public static function width(string $codePage, string $style, string $bytes): int
    {
        $widths = self::widths($codePage, $style);
        $total  = 0;

        for ($i = 0, $length = strlen($bytes); $i < $length; $i++) {
            $total += $widths[$bytes[$i]] ?? 0;
        }

        return $total;
    }

    /** Builds both directions of a code page's character map from its definition file's $uv. */
    private static function map(string $codePage): void
    {
        if (!in_array($codePage, self::CODE_PAGES, true)) {
            throw new PdfException("Unknown code page '{$codePage}'");
        }

        $bytes      = [];
        $codePoints = [];

        // $uv is byte => code point, or byte => [first code point, how many in a row].
        foreach (self::definition(self::file($codePage, self::REGULAR))['uv'] as $byte => $range) {
            [$first, $count] = is_array($range) ? $range : [$range, 1];

            for ($i = 0; $i < $count; $i++) {
                // Control characters are never drawn.
                if ($byte + $i >= 0x20 && $byte + $i !== 0x7F) {
                    $bytes[$first + $i] ??= $byte + $i;
                    $codePoints[$byte + $i] = $first + $i;
                }
            }
        }

        self::$bytes[$codePage]      = $bytes;
        self::$codePoints[$codePage] = $codePoints;
    }

    /** @return array<string, mixed> the variables a makefont definition file sets ($cw, $uv, …) */
    private static function definition(string $file): array
    {
        if (!isset(self::$definitions[$file])) {
            $path = self::DIR . $file;

            if (!is_file($path)) {
                throw new PdfException("The font file {$file} is missing from the pdf service's fonts directory");
            }

            self::$definitions[$file] = (static function (string $path): array {
                include $path;

                return get_defined_vars();
            })($path);
        }

        return self::$definitions[$file];
    }
}
